<?php
session_start();
if(empty($_SESSION['user_id'])){header('Location:/pages/login.php');exit;}
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/helpers/book_image_helper.php';
$userId=(int)$_SESSION['user_id'];$bookId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$bookId){header('Location:/pages/profile.php?tab=selling');exit;}
$stmt=$pdo->prepare("SELECT * FROM books WHERE book_id=? AND seller_type='user' AND seller_id=? AND book_type='used'");$stmt->execute([$bookId,$userId]);$book=$stmt->fetch(PDO::FETCH_ASSOC);if(!$book){http_response_code(403);exit('ไม่พบสินค้า หรือคุณไม่มีสิทธิ์แก้ไขสินค้านี้');}
$success='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  $dir=__DIR__.'/uploads/books/';if(!is_dir($dir))mkdir($dir,0755,true);$newImages=handleBookImages(['image_cover','image_back','image_inside','image_edge'],$dir);
  foreach($newImages as $key=>$value)if(!$value)$newImages[$key]=$book[$key];
  $update=$pdo->prepare("UPDATE books SET isbn=?,title=?,author=?,publisher_name=?,category=?,format=?,pages=?,dimensions=?,language=?,synopsis=?,condition_level=?,defects_detail=?,price=?,original_price=?,status=?,image_cover=?,image_back=?,image_inside=?,image_edge=? WHERE book_id=? AND seller_type='user' AND seller_id=?");
  $update->execute([trim($_POST['isbn']??''),trim($_POST['title']??''),trim($_POST['author']??''),trim($_POST['publisher_name']??''),trim($_POST['category']??''),trim($_POST['format']??''),(int)($_POST['pages']??0),trim($_POST['dimensions']??''),trim($_POST['language']??'ไทย'),trim($_POST['synopsis']??''),$_POST['condition_level']??'good',trim($_POST['defects_detail']??''),(float)($_POST['price']??0),(float)($_POST['original_price']??0),$_POST['status']??'available',$newImages['image_cover'],$newImages['image_back'],$newImages['image_inside'],$newImages['image_edge'],$bookId,$userId]);
  $stmt->execute([$bookId,$userId]);$book=$stmt->fetch(PDO::FETCH_ASSOC);$success='บันทึกการแก้ไขเรียบร้อยแล้ว';
 }catch(Throwable $e){$error='ไม่สามารถบันทึกข้อมูลได้ กรุณาลองใหม่';}
}
$categories=['วรรณกรรมไทย','วรรณกรรมต่างประเทศ','การ์ตูน/มังงะ','จิตวิทยา','การศึกษา/ตำรา','ธุรกิจ/การเงิน','เทคโนโลยี','สุขภาพ/ความงาม','ท่องเที่ยว','ศาสนา/ปรัชญา','ประวัติศาสตร์','สิ่งแวดล้อม','อื่น ๆ'];
function eu(string $v):string{return htmlspecialchars($v);}function euImage(?string $v):?string{if(!$v)return null;if(preg_match('#^https?://#',$v))return $v;$v=ltrim(str_replace('\\','/',$v),'/');return str_starts_with($v,'uploads/')?'/pages/'.$v:'/assets/image/books/'.$v;}
?>
<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>แก้ไขหนังสือมือสอง - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css"><style>
*{box-sizing:border-box}.edit-wrap{max-width:960px;margin:auto;padding:42px 24px 85px}.back{color:var(--secondary-color);text-decoration:none}.title{font-size:32px;color:var(--secondary-color);margin:18px 0 28px}.card{background:#fff;border:1px solid #dfd6ce;border-radius:15px;padding:27px;margin-bottom:20px}.card h2{color:var(--secondary-color);font-size:19px;margin:0 0 20px;padding-bottom:10px;border-bottom:1px solid #eaded7}.grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}.field{margin-bottom:16px}.field label{display:block;font-weight:600;color:#655c56;margin-bottom:7px}.field input,.field select,.field textarea{width:100%;padding:12px;border:1px solid #ccd3c5;border-radius:8px;background:#fff;font:inherit}.field textarea{min-height:105px}.images{display:grid;grid-template-columns:repeat(2,1fr);gap:17px}.image-slot{min-height:245px;border:2px dashed #cbd2c4;border-radius:11px;padding:12px;text-align:center;display:flex;flex-direction:column;gap:9px;justify-content:center;overflow:hidden}.image-slot img{width:100%;height:190px;object-fit:contain;background:#f7f3f0;border-radius:8px}.image-slot input{width:100%}.actions{display:flex;gap:12px}.btn{height:50px;min-width:190px;border-radius:8px;font:inherit;font-weight:600;display:grid;place-items:center;text-decoration:none;cursor:pointer}.save{border:0;background:var(--secondary-color);color:#fff}.cancel{border:1px solid var(--secondary-color);color:var(--secondary-color);background:#fff}.notice{padding:14px 17px;border-radius:8px;margin-bottom:18px}.ok{background:#e9f5e4;color:#47723e}.bad{background:#fde6e1;color:#a34b44}@media(max-width:700px){.edit-wrap{padding:28px 15px 65px}.card{padding:19px}.grid,.images{grid-template-columns:1fr}.actions{flex-direction:column}.btn{width:100%}}
</style></head><body><?php require __DIR__.'/../components/header.php';?><main class="edit-wrap"><a class="back" href="/pages/profile.php?tab=selling">← กลับหน้าโปรไฟล์</a><h1 class="title">แก้ไขรายละเอียดหนังสือมือสอง</h1><?php if($success):?><div class="notice ok"><?=eu($success)?></div><?php endif;?><?php if($error):?><div class="notice bad"><?=eu($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><section class="card"><h2>ข้อมูลหนังสือ</h2><div class="grid"><div class="field"><label>ISBN</label><input name="isbn" value="<?=eu($book['isbn']??'')?>"></div><div class="field"><label>ชื่อหนังสือ *</label><input name="title" required value="<?=eu($book['title'])?>"></div><div class="field"><label>ผู้เขียน</label><input name="author" value="<?=eu($book['author']??'')?>"></div><div class="field"><label>สำนักพิมพ์</label><input name="publisher_name" value="<?=eu($book['publisher_name']??'')?>"></div><div class="field"><label>หมวดหมู่</label><select name="category"><option value="">เลือกหมวดหมู่</option><?php foreach($categories as $cat):?><option value="<?=eu($cat)?>" <?=$book['category']===$cat?'selected':''?>><?=eu($cat)?></option><?php endforeach;?></select></div><div class="field"><label>ภาษา</label><input name="language" value="<?=eu($book['language']??'ไทย')?>"></div><div class="field"><label>รูปแบบ</label><input name="format" value="<?=eu($book['format']??'')?>"></div><div class="field"><label>จำนวนหน้า</label><input type="number" min="1" name="pages" value="<?=eu((string)($book['pages']??''))?>"></div><div class="field"><label>ขนาดหนังสือ</label><input name="dimensions" value="<?=eu($book['dimensions']??'')?>"></div><div class="field"><label>สถานะโพสต์</label><select name="status"><option value="available" <?=$book['status']==='available'?'selected':''?>>วางขายอยู่</option><option value="hidden" <?=$book['status']==='hidden'?'selected':''?>>ซ่อนชั่วคราว</option><option value="draft" <?=$book['status']==='draft'?'selected':''?>>ฉบับร่าง</option></select></div></div><div class="field"><label>เรื่องย่อ / รายละเอียด</label><textarea name="synopsis"><?=eu($book['synopsis']??'')?></textarea></div></section>
<section class="card"><h2>สภาพและราคา</h2><div class="grid"><div class="field"><label>ราคาขาย *</label><input type="number" min="1" step=".01" name="price" required value="<?=eu((string)$book['price'])?>"></div><div class="field"><label>ราคาปก</label><input type="number" min="0" step=".01" name="original_price" value="<?=eu((string)($book['original_price']??0))?>"></div><div class="field"><label>สภาพหนังสือ</label><select name="condition_level"><?php foreach(['good'=>'สภาพดี','fair'=>'มีตำหนิเล็กน้อย','old'=>'สภาพเก่า'] as $value=>$label):?><option value="<?=$value?>" <?=$book['condition_level']===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div></div><div class="field"><label>รายละเอียดตำหนิ</label><textarea name="defects_detail"><?=eu($book['defects_detail']??'')?></textarea></div></section>
<section class="card"><h2>รูปภาพสภาพจริง</h2><div class="images"><?php foreach(['image_cover'=>'หน้าปก','image_back'=>'หลังปก','image_inside'=>'ด้านใน','image_edge'=>'สัน/ขอบ'] as $field=>$label):?><label class="image-slot"><strong><?=$label?></strong><img id="preview-<?=$field?>" src="<?=eu(euImage($book[$field]??null)??'')?>" alt="<?=$label?>"><input type="file" name="<?=$field?>" accept="image/*" onchange="previewEdit(this,'<?=$field?>')"></label><?php endforeach;?></div></section><div class="actions"><button class="btn save" type="submit">บันทึกการแก้ไข</button><a class="btn cancel" href="/pages/profile.php?tab=selling">ยกเลิก</a></div></form></main><?php require __DIR__.'/../components/footer.php';?><script>const editUrls={};function previewEdit(input,key){const file=input.files&&input.files[0];if(!file)return;if(editUrls[key])URL.revokeObjectURL(editUrls[key]);editUrls[key]=URL.createObjectURL(file);document.getElementById('preview-'+key).src=editUrls[key]}</script></body></html>
